def solve(n: int) -> int:
    total = 0
    while n:
        total += n % 10
        n //= 10
    return total

def solve(n: int) -> str:
    if n % 15 == 0:
        return "FizzBuzz"
    if n % 3 == 0:
        return "Fizz"
    if n % 5 == 0:
        return "Buzz"
    return str(n)

import math

def solve(n: int) -> bool:
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    for divisor in range(3, math.isqrt(n) + 1, 2):
        if n % divisor == 0:
            return False
    return True

def solve(items: list) -> list:
    result = items[:]
    for i in range(0, len(result) - 1, 2):
        result[i], result[i + 1] = result[i + 1], result[i]
    return result

def solve(a: list, b: list) -> list:
    result = []
    for i in range(max(len(a), len(b))):
        if i < len(a):
            result.append(a[i])
        if i < len(b):
            result.append(b[i])
    return result

def solve(s: str) -> int:
    words = s.split()
    return len(words[-1]) if words else 0

def solve(word: str) -> str:
    if len(word) <= 3:
        return word
    return word[0] + str(len(word) - 2) + word[-1]

def solve(n: int) -> int:
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def solve(words: list) -> str:
    if not words:
        return ""
    if len(words) == 1:
        return words[0]
    return ", ".join(words[:-1]) + " and " + words[-1]
